def find_largest_block(config, k):
    N = len(config)
    if k > N or k <= 0:
        return None, None

    k_idx = k - 1  # 0-based index
    target_metal = config[k_idx]

    # 1. Find the start and end of the largest contiguous block containing k_idx
    start = k_idx
    while start > 0 and config[start - 1] == target_metal:
        start -= 1

    end = k_idx
    while end < N - 1 and config[end + 1] == target_metal:
        end += 1

    # The block is config[start:end+1]
    block = config[start:end+1]

    # 2. Determine the remaining sequence
    remaining = config[:start] + config[end+1:]

    # 3. Construct the new configuration
    new_config = block + remaining
    return new_config

def simulate_process(initial_config, k, max_steps=100):
    config = list(initial_config)
    history = [initial_config]

    for step in range(max_steps):
        # Check termination condition: at most one metal boundary
        boundaries = 0
        for i in range(len(config) - 1):
            if config[i] != config[i+1]:
                boundaries += 1

        if boundaries <= 1:
            return "Terminated successfully", config

        try:
            new_config_str = find_largest_block("".join(config), k)
            if new_config_str is None:
                 return "Error: Invalid k", config

            new_config = list(new_config_str)
            if new_config == config:
                 return "Stagnated", config

            config = new_config
            history.append("".join(config))

        except Exception as e:
            return f"Error during simulation: {e}", config

    return "Max steps reached", "".join(config)

