def solve_for_n(n):
    total_coins = 2 * n
    configurations = []
    import itertools
    for config in itertools.product(['A', 'C'], repeat=total_coins):
        if config.count('A') == n and config.count('C') == n:
            configurations.append(list(config))

    def get_boundaries(config):
        count = 0
        for i in range(len(config) - 1):
            if config[i] != config[i+1]:
                count += 1
        return count

    valid_ks = []
    for k in range(1, total_coins + 1):
        all_configs_ok = True
        for config in configurations:
            current_config = list(config)
            visited = set()
            while True:
                config_tuple = tuple(current_config)
                if config_tuple in visited:
                    break
                visited.add(config_tuple)

                if get_boundaries(current_config) <= 1:
                    break

                # Identify k-th coin (1-indexed)
                k_idx = k - 1
                coin_type = current_config[k_idx]

                # Find largest consecutive block containing k_idx
                start = k_idx
                while start > 0 and current_config[start-1] == coin_type:
                    start -= 1
                end = k_idx
                while end < total_coins - 1 and current_config[end+1] == coin_type:
                    end += 1

                # Subsequence to move
                subsequence = current_config[start:end+1]
                # Remaining coins
                remaining = current_config[:start] + current_config[end+1:]
                # New configuration
                current_config = subsequence + remaining

            if get_boundaries(current_config) > 1:
                all_configs_ok = False
                break

        if all_configs_ok:
            valid_ks.append(k)
    return valid_ks

